    toks=list(map(int,f.read().split()))
it=iter(toks); n_jobs=next(it); n_machines=next(it)
ops=[]
for j in range(n_jobs):
    n_ops=next(it); job=[]
    for o in range(n_ops):
        k=next(it); alts=[]
        for _ in range(k):
            m=next(it); d=next(it); alts.append((m,d))
        job.append(alts)
    ops.append(job)
with open('/app/data/baseline_solution.json') as f: baseline=json.load(f)
base_by={(x['job'],x['op']):x for x in baseline['schedule']}
with open('/app/data/policy.json') as f: policy=json.load(f)
downtimes={m:[] for m in range(n_machines)}
with open('/app/data/downtime.csv') as f:
    for r in csv.DictReader(f): downtimes[int(r['machine'])].append((int(r['start']),int(r['end'])))
freeze_until=policy['freeze']['freeze_until']
# choose locks: baseline ops completed by freeze_until
locked={(x['job'],x['op']):x for x in baseline['schedule'] if x['end'] <= freeze_until}
print('locked', locked)

all_ops=[(j,o) for j in range(n_jobs) for o in range(len(ops[j]))]
