base_s={k:v['start'] for k,v in base_by.items()}
base_e={k:v['end'] for k,v in base_by.items()}

def fit_start(machine, earliest, dur, intervals):
    """earliest start >= earliest not overlapping existing machine intervals or downtimes."""
    t=earliest
    blocked=sorted(intervals + downtimes[machine])
    changed=True
    while True:
        moved=False
        for a,b in blocked:
            if t < b and t+dur > a:  # overlap
                t=b; moved=True; break
        if not moved: return t

def validate_sched(sched, verbose=False):
    by={(x['job'],x['op']):x for x in sched}
    ok=True; msgs=[]
    if len(by)!=sum(len(job) for job in ops): ok=False; msgs.append('missing/duplicate')
    for j,job in enumerate(ops):
        for o,alts in enumerate(job):
            x=by.get((j,o))
            if x is None: continue
            if x['end']-x['start']!=x['dur']: ok=False; msgs.append(f'dur arithmetic {j,o}')
            if (x['machine'],x['dur']) not in alts: ok=False; msgs.append(f'invalid alt {j,o} {x}')
            if o>0 and by[(j,o-1)]['end']>x['start']: ok=False; msgs.append(f'precedence {j,o}')
    for m in range(n_machines):
        ints=sorted([(x['start'],x['end'],x) for x in sched if x['machine']==m])
        for (a,b,x),(c,d,y) in zip(ints,ints[1:]):
            if b>c: ok=False; msgs.append(f'machine overlap m{m} {x} {y}')
        for a,b,x in ints:
            for c,d in downtimes[m]:
                if max(a,c)<min(b,d): ok=False; msgs.append(f'downtime m{m} {x} dt{c,d}')
    # locked end<=freeze
    for k,lb in locked.items():
        x=by[k]
        for fld in policy['freeze']['lock_fields']:
            if x[fld]!=lb[fld]: ok=False; msgs.append(f'locked {k} {fld}')
    machine_changes=sum(1 for x in sched if x['machine'] != base_m[(x['job'],x['op'])])
    start_shift=sum(abs(x['start']-base_s[(x['job'],x['op'])]) for x in sched)
    makespan=max(x['end'] for x in sched)
    if machine_changes>policy['change_budget']['max_machine_changes']: ok=False; msgs.append(f'machine_changes {machine_changes}')
    if start_shift>policy['change_budget']['max_total_start_shift_L1']: ok=False; msgs.append(f'start_shift {start_shift}')
    if verbose:
        print('ok',ok,'makespan',makespan,'changes',machine_changes,'shift',start_shift,'msgs',msgs)
    return ok,makespan,machine_changes,start_shift,msgs

# assignment enumeration within budget and locks
assignments=[]
keys=all_ops
alts_by={k:ops[k[0]][k[1]] for k in keys}
def enum_assign(i, cur, changes):
    if changes>4: return
    if i==len(keys): assignments.append(cur.copy()); return
    k=keys[i]
    if k in locked:
        cur[k]=(locked[k]['machine'], locked[k]['dur']); enum_assign(i+1,cur,changes); cur.pop(k); return
    for m,d in alts_by[k]:
        cur[k]=(m,d)
        enum_assign(i+1,cur, changes + (m!=base_m[k]))
        cur.pop(k)
enum_assign(0,{},0)
print('assignments',len(assignments))

