# Continue by doing an exact feasibility search for makespan < 36 under policy budgets.
# We'll search all starts on integer grid, with currently chosen interpretation: completed by freeze_until locked.
# It is the only feasible interpretation because baseline operations starting at 5 overlap downtime.
H=35

# All machine assignment variants already computed. Exact placement DFS with variable ordering.
def feasible_with_makespan(assign, H=35, max_solutions=1, time_limit_nodes=1000000):
    domains={}
    for j,o in all_ops:
        m,d=assign[(j,o)]
        if (j,o) in locked:
            lb=locked[(j,o)]
            if lb['end']>H: return []
            domains[(j,o)]=[lb['start']]
        else:
            # start 0..H-d, not overlap downtime on assigned machine
            starts=[]
            for s in range(0,H-d+1):
                e=s+d
                if all(not (max(s,a)<min(e,b)) for a,b in downtimes[m]):
                    starts.append(s)
            if not starts: return []
            domains[(j,o)]=starts
    sol=[]; nodes=0
    assigned={}
    mach_ints={m:[] for m in range(n_machines)}
    # put locked first
    order=[]
    # dynamic variable choice
    def consistent(k,s):
        j,o=k; m,d=assign[k]; e=s+d
        if e>H: return False
        # precedence with assigned neighbors
        if o>0 and (j,o-1) in assigned:
            if assigned[(j,o-1)] + assign[(j,o-1)][1] > s: return False
        if o+1 < len(ops[j]) and (j,o+1) in assigned:
            if e > assigned[(j,o+1)]: return False
        # machine intervals
        for a,b in mach_ints[m]:
            if max(s,a)<min(e,b): return False
        return True
    def partial_budget_possible():
        # compute minimum possible start shift given assigned and precedence loose? simple lower bound assigned only
        sh=0
        for k,s in assigned.items(): sh += abs(s-base_s[k])
        return sh <= policy['change_budget']['max_total_start_shift_L1']
    def rec():
        nonlocal nodes
        nodes +=1
        if nodes>time_limit_nodes: return False
        if len(assigned)==len(all_ops):
            sched=[]
            for k,s in assigned.items():
                j,o=k; m,d=assign[k]; sched.append({'job':j,'op':o,'machine':m,'start':s,'end':s+d,'dur':d})
            sched=sorted(sched,key=lambda x:(x['start'],x['machine'],x['job'],x['op']))
            ok,ms,ch,sh,msgs=validate_sched(sched)
            if ok and ms<=H:
                sol.append(sched); return True
            return False
        # choose unassigned with smallest legal remaining domain after filtering; prioritize constraints
        bestk=None; bestvals=None
        for k in all_ops:
            if k in assigned: continue
            vals=[]
            for s in domains[k]:
                if consistent(k,s): vals.append(s)
            if bestvals is None or len(vals)<len(bestvals):
                bestk=k; bestvals=vals
                if len(vals)==0: break
        if not bestvals: return False
        # sort values by close baseline / early
        bestvals=sorted(bestvals,key=lambda s:(abs(s-base_s[bestk]), s))
        j,o=bestk; m,d=assign[bestk]
        for s in bestvals:
            assigned[bestk]=s; mach_ints[m].append((s,s+d))
            if partial_budget_possible():
                if rec() and len(sol)>=max_solutions: return True
            mach_ints[m].pop(); assigned.pop(bestk)
        return False
    # machine changes already should fit
    if sum(1 for k,(m,d) in assign.items() if m!=base_m[k])>policy['change_budget']['max_machine_changes']:
        return []
    rec()
    return sol

